import java.io.*;
import java.util.*;

public class Main {
    static final InputStream in = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int gc() throws IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    static String token() throws IOException {
        int c = gc();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = gc();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = gc(); }
        return sb.toString();
    }

    static long[] x, y;
    static String[] names;
    static int best;
    static long bd;

    static void consider(int j, int q) {
        long d = Math.abs(x[j] - x[q]) + Math.abs(y[j] - y[q]);
        if (best < 0 || d < bd || (d == bd && names[j].compareTo(names[best]) < 0)) { best = j; bd = d; }
    }

    public static void main(String[] args) throws IOException {
        int n = Integer.parseInt(token());
        names = new String[n];
        x = new long[n];
        y = new long[n];
        HashMap<String, Integer> id = new HashMap<>(2 * n + 1);
        for (int i = 0; i < n; i++) {
            names[i] = token();
            x[i] = Long.parseLong(token());
            y[i] = Long.parseLong(token());
            id.put(names[i], i);
        }
        // Sort by (x, y) and (y, x); on a shared line the nearest city is an adjacent one.
        Integer[] bx = new Integer[n], by = new Integer[n];
        for (int i = 0; i < n; i++) bx[i] = by[i] = i;
        Arrays.sort(bx, (a, b) -> x[a] != x[b] ? Long.compare(x[a], x[b]) : Long.compare(y[a], y[b]));
        Arrays.sort(by, (a, b) -> y[a] != y[b] ? Long.compare(y[a], y[b]) : Long.compare(x[a], x[b]));
        int[] px = new int[n], py = new int[n];
        for (int i = 0; i < n; i++) { px[bx[i]] = i; py[by[i]] = i; }
        int m = Integer.parseInt(token());
        StringBuilder out = new StringBuilder();
        for (int k = 0; k < m; k++) {
            int q = id.get(token());
            best = -1;
            bd = 0;
            int p = px[q];
            if (p > 0 && x[bx[p - 1]] == x[q]) consider(bx[p - 1], q);
            if (p + 1 < n && x[bx[p + 1]] == x[q]) consider(bx[p + 1], q);
            p = py[q];
            if (p > 0 && y[by[p - 1]] == y[q]) consider(by[p - 1], q);
            if (p + 1 < n && y[by[p + 1]] == y[q]) consider(by[p + 1], q);
            out.append(best < 0 ? "NONE" : names[best]).append('\n');
        }
        System.out.print(out);
    }
}

package main

import (
	"bufio"
	"os"
	"sort"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<16), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() string { sc.Scan(); return sc.Text() }
	atoi := func(s string) int64 { v, _ := strconv.ParseInt(s, 10, 64); return v }
	n := int(atoi(next()))
	names := make([]string, n)
	x, y := make([]int64, n), make([]int64, n)
	id := make(map[string]int, n)
	for i := 0; i < n; i++ {
		names[i] = next()
		x[i], y[i] = atoi(next()), atoi(next())
		id[names[i]] = i
	}
	// Sort by (x, y) and (y, x); on a shared line the nearest city is an adjacent one.
	bx, by := make([]int, n), make([]int, n)
	for i := range bx {
		bx[i], by[i] = i, i
	}
	sort.Slice(bx, func(a, b int) bool {
		i, j := bx[a], bx[b]
		if x[i] != x[j] {
			return x[i] < x[j]
		}
		return y[i] < y[j]
	})
	sort.Slice(by, func(a, b int) bool {
		i, j := by[a], by[b]
		if y[i] != y[j] {
			return y[i] < y[j]
		}
		return x[i] < x[j]
	})
	px, py := make([]int, n), make([]int, n)
	for i := 0; i < n; i++ {
		px[bx[i]], py[by[i]] = i, i
	}
	abs := func(v int64) int64 {
		if v < 0 {
			return -v
		}
		return v
	}
	m := int(atoi(next()))
	w := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer w.Flush()
	for k := 0; k < m; k++ {
		q := id[next()]
		best, bd := -1, int64(0)
		consider := func(j int) {
			d := abs(x[j]-x[q]) + abs(y[j]-y[q])
			if best < 0 || d < bd || (d == bd && names[j] < names[best]) {
				best, bd = j, d
			}
		}
		p := px[q]
		if p > 0 && x[bx[p-1]] == x[q] {
			consider(bx[p-1])
		}
		if p+1 < n && x[bx[p+1]] == x[q] {
			consider(bx[p+1])
		}
		p = py[q]
		if p > 0 && y[by[p-1]] == y[q] {
			consider(by[p-1])
		}
		if p+1 < n && y[by[p+1]] == y[q] {
			consider(by[p+1])
		}
		if best < 0 {
			w.WriteString("NONE\n")
		} else {
			w.WriteString(names[best])
			w.WriteByte('\n')
		}
	}
}
